/* api-generation.js — connects column 1 (Idea Generation) to the real ideation
 * daemon in the repo's website/ideation/.
 *
 * Two things happen when the daemon answers:
 *   - `generateIdeas` (the seed box and the Iterate popover) calls POST /api/generate,
 *     so generation is real instead of mocked;
 *   - the ideas the daemon has already generated by monitoring the internet are
 *     loaded from GET /api/tree into the same level tree the column renders
 *     (abstract ideas at level 1, concrete ideas at level 2).
 *
 * Where the daemon is looked for:
 *   - the same origin, when the page is served by the daemon, or
 *   - http://localhost:8091, when the page is served by ./run.sh on port 8000.
 *   Override with  window.ID_API = 'http://host:port'  before this script loads.
 *
 * It swaps Hack.mockBackend.generateIdeas in place (actions.js looks it up on every
 * call), so the UI code does not change.
 */
(function () {
  const Hack = (window.Hack = window.Hack || {});
  const mock = Hack.mockBackend;
  const fallback = mock.generateIdeas;
  const info = (Hack.ideationInfo = { live: false, base: '' });

  async function getJSON(path, opts) {
    const r = await fetch(info.base + path, opts);
    const body = await r.json().catch(() => ({}));
    if (!r.ok) throw Object.assign(new Error(body.error || `HTTP ${r.status}`), { status: r.status, body });
    return body;
  }
  const post = (path, body) => getJSON(path, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}),
  });

  function generateIdeas(args) {
    if (!info.live) return fallback(args);
    return post('/api/generate', {
      sourceIdeas: args.sourceIdeas || [],
      iterationType: args.iterationType,
      variationCount: args.variationCount,
      freeformPrompt: args.freeformPrompt,
      seedText: args.seedText,
      model: args.model,
    });
  }

  /** Merge the daemon's ideas into the level tree (deduped by id). */
  function ensureLevel(level) {
    const state = Hack.store.state;
    let lvl = state.levels.find((l) => l.level === level);
    if (!lvl) {
      lvl = { level, ideas: [], iteration: { type: 'refinement', variationCount: 2, freeformPrompt: '' }, pending: 0, error: null };
      state.levels.push(lvl);
      state.levels.sort((a, b) => a.level - b.level);
    }
    return lvl;
  }

  function mergeTree(tree) {
    const state = Hack.store.state;
    let added = 0;
    for (const lvl of tree.levels || []) {
      const target = ensureLevel(lvl.level);
      for (const idea of lvl.ideas || []) {
        if (target.ideas.some((i) => i.id === idea.id)) continue;
        target.ideas.push({
          id: idea.id, text: idea.text, kind: idea.kind,
          justification: idea.justification || [], sources: idea.sources || [],
          tags: idea.tags || [], score: idea.score || {}, artifactType: idea.artifact_type || '',
          topicId: idea.topic_id, topicName: idea.topic_name,
          level: lvl.level, parentIdeaIds: [], lineage: [], subject: idea.topic_name || '',
        });
        added += 1;
      }
    }
    if (added) Hack.store.notify();
    return added;
  }

  async function loadTree() {
    if (!info.live) return 0;
    try {
      const tree = await getJSON('/api/tree');
      return mergeTree(tree);
    } catch (e) {
      return 0;
    }
  }

  async function detect() {
    const candidates = window.ID_API !== undefined ? [window.ID_API] : ['', 'http://localhost:8091'];
    for (const base of candidates) {
      try { info.base = base; await getJSON('/health'); info.live = true; break; }
      catch (e) { info.base = ''; info.live = false; }
    }
    if (!info.live) return;
    Hack.store.notify();
    if (Hack.actions && document.getElementById('col-generation')) {
      Hack.actions.showToast('Ideation connected: generation is real.', 'ok');
    }
    await loadTree();
  }

  mock.generateIdeas = generateIdeas;
  Hack.apiGeneration = { detect, info, loadTree, generateIdeas };
  window.addEventListener('load', detect);
})();
